window.kbPageData["views/entry/k-a15abd6c20b30588"] = {"key":"entry/k-a15abd6c20b30588","state":{"route":"entry/k-a15abd6c20b30588"},"node":{"id":"k-a15abd6c20b30588","mode":"k","title":"历史唯物主义 · 社会的基本矛盾","type":"原理与机制","domain":"哲学","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["原理与机制"],"出处性质":["理论手册"],"学科":["哲学"],"来源主题":["马克思主义哲学"],"资料类别":["非时政"]},"directorySummary":"二、社会的基本矛盾\n社会基本矛盾包括两方面，即生产力和生产关系之间的矛盾、经济基础和上层建筑之间\n的矛盾。\n生产力决定生产关系。生产关系反作用于生产力。生产关系对生产力反作用的性质取决\n于生产关系是否适应生产力的状况。\n◎粉笔拓展\n2023 年 9 月，习近平总书记在黑龙江考察调研期间首次提到“新质…","sources":[{"id":"9e62b2622b12e9cc","label":"历史唯物主义 · 社会的基本矛盾","topic":"马克思主义哲学","category":"非时政","text":"二、社会的基本矛盾\n社会基本矛盾包括两方面，即生产力和生产关系之间的矛盾、经济基础和上层建筑之间\n的矛盾。\n生产力决定生产关系。生产关系反作用于生产力。生产关系对生产力反作用的性质取决\n于生产关系是否适应生产力的状况。\n◎粉笔拓展\n2023 年 9 月，习近平总书记在黑龙江考察调研期间首次提到“新质生产力”。\n新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、\n高效能、高质量特征，符合新发展理念的先进生产力质态。它由技术革命性突破、生产要素\n创新性配置、产业深度转型升级而催生，以劳动者、劳动资料、劳动对象及其优化组合的跃\n升为基本内涵，以全要素生产率大幅提升为核心标志，特点是创新，关键在质优，本质是先\n进生产力。\n经济基础决定上层建筑。上层建筑反作用于经济基础，这种反作用集中体现在为自己的\n经济基础服务。\n（粉笔敲黑板：明确社会基本矛盾包括什么，其次做题时注意判断这两方面矛盾贯穿于\n社会发展的始终，并不能进行消除）","source":{"doc":"3ccc56f4000d1642c2d1","first":6,"last":6,"page":6,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-a15abd6c20b30588":[]}};
